INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S1-Q18$batch11$, 159, 1, 18, $batch11$Must Be True$batch11$, $batch11$Putting a tap in a healthy maple that has a trunk 12 or more inches in diameter will not harm the tree. Silver maples, red maples, and Manitoba maples can all be tapped for making maple syrup. The sugar maple, however, is best for syrup making, because of all the maples its sap has the highest concentration of sugar.$batch11$, $batch11$If the statements above are true, which one of the following must also be true?$batch11$, $batch11$A$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$A maple whose trunk is more than 12 inches in diameter is unhealthy if it is harmed by tapping.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$The healthiest maple trees are usually those with the largest trunks.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$A maple tree that has been harmed will produce very little sap.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Putting a tap into an unhealthy maple tree that is less than 12 inches in diameter will harm it.$batch11$, $batch11$Negated$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The maple trees most commonly used for making syrup are sugar maples.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Tapping a healthy maple with a trunk 12 inches or wider will not harm it. Several kinds of maple can be tapped. Sugar maples are best for syrup.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Healthy and 12+ inches → tapping won't harm. Take the contrapositive: if tapping harms a tree, it's not healthy or it's under 12 inches. If a tree is over 12 inches and tapping harms it, it must be unhealthy.$batch11$), (2, $batch11$Goal$batch11$, $batch11$A tree over 12 inches that is harmed by tapping is unhealthy.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Harmed by tapping means not healthy or under 12 inches. It's over 12 inches, so it's unhealthy.$batch11$), ($batch11$B$batch11$, $batch11$Health and trunk size are never linked.$batch11$), ($batch11$C$batch11$, $batch11$Sap production of harmed trees never comes up.$batch11$), ($batch11$D$batch11$, $batch11$Healthy and large → no harm. Failing both conditions doesn't mean harm will happen.$batch11$), ($batch11$E$batch11$, $batch11$Sugar maples are best for syrup. That doesn't make them most commonly used.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S1-Q18$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
